import type { ReportSourceScope } from './searchReport';

export type SearchReportJobStatus = 'generating' | 'completed' | 'failed';

export type SearchReportGeneratedDocument = {
  title: string;
  generatedAt: string;
  fileName: string;
};

export type SearchReportJob = {
  id: string;
  turnId: string;
  title: string;
  progress: number;
  status: SearchReportJobStatus;
  sourceScope: ReportSourceScope;
  sourceCount: number;
  completedAt?: string;
  generatedDocument?: SearchReportGeneratedDocument;
};

export type SearchReportTurnJobs = {
  jobs: SearchReportJob[];
  activeIndex: number;
};

export function appendSearchReportJob(
  prev: SearchReportTurnJobs | undefined,
  job: SearchReportJob
): SearchReportTurnJobs {
  const jobs = prev ? [...prev.jobs, job] : [job];
  return { jobs, activeIndex: jobs.length - 1 };
}

export function isTurnReportGenerating(turnJobs?: SearchReportTurnJobs): boolean {
  return turnJobs?.jobs.some((job) => job.status === 'generating') ?? false;
}

export function getActiveSearchReportJob(turnJobs?: SearchReportTurnJobs): SearchReportJob | null {
  if (!turnJobs || turnJobs.jobs.length === 0) return null;
  const index = Math.min(Math.max(0, turnJobs.activeIndex), turnJobs.jobs.length - 1);
  return turnJobs.jobs[index] ?? null;
}

export function shiftSearchReportJobIndex(
  turnJobs: SearchReportTurnJobs,
  delta: number
): SearchReportTurnJobs {
  const nextIndex = Math.min(Math.max(0, turnJobs.activeIndex + delta), turnJobs.jobs.length - 1);
  if (nextIndex === turnJobs.activeIndex) return turnJobs;
  return { ...turnJobs, activeIndex: nextIndex };
}

export const SEARCH_REPORT_MAIN_STEPS = [
  '整理本轮问答与来源范围',
  '归纳检索要点与引用结构',
  '交叉比对来源与回答一致性',
  '检索法规案例补充论证脉络',
  '生成检索报告文档与格式润色',
];

export type ExecutionLogEntry = {
  text: string;
  type?: 'info' | 'success' | 'warning';
  active?: boolean;
};

const SCOPE_LABEL: Record<ReportSourceScope, string> = {
  cited: '本轮引用来源',
  all_turn: '本轮全部参考来源',
  filtered: '当前筛选结果',
};

export function getSearchReportStepIndex(progress: number, isCompleted: boolean): number {
  if (isCompleted) return SEARCH_REPORT_MAIN_STEPS.length;
  if (progress < 15) return 0;
  if (progress < 30) return 1;
  if (progress < 55) return 2;
  if (progress < 80) return 3;
  return 4;
}

export function buildSearchReportExecutionLogs(
  progress: number,
  isCompleted: boolean,
  sourceCount: number,
  sourceScope: ReportSourceScope
): ExecutionLogEntry[] {
  const logs: ExecutionLogEntry[] = [];
  const scopeLabel = SCOPE_LABEL[sourceScope];

  if (progress >= 0) {
    logs.push({ text: '初始化检索报告任务，分配生成资源...', type: 'info' });
  }
  if (progress >= 2) {
    logs.push({
      text: `正在读取 ${scopeLabel}，共 ${sourceCount} 条来源...`,
      active: progress < 15,
    });
  }
  if (progress >= 15) {
    logs.push({ text: `来源读取完成：已加载 ${sourceCount} 条参考条目`, type: 'success' });
  }
  if (progress >= 18) {
    logs.push({
      text: '正在提取用户问题、AI 回答与引用角标映射...',
      active: progress < 30,
    });
  }
  if (progress >= 30) {
    logs.push({ text: '检索要点归纳完成，已建立报告章节骨架', type: 'success' });
    logs.push({ text: '启动子任务 [来源一致性审查] 进行交叉比对...', type: 'info' });
  }
  if (progress >= 45) {
    logs.push({
      text: '正在比对回答表述与来源原文，标记需补充引证段落...',
      active: progress < 55,
    });
  }
  if (progress >= 55) {
    logs.push({ text: '来源与回答一致性审查完成', type: 'success' });
  }
  if (progress >= 58) {
    logs.push({
      text: '正在检索相关法规、案例以补充论证脉络...',
      active: progress < 80,
    });
  }
  if (progress >= 80) {
    logs.push({ text: '法理依据与类案检索完成', type: 'success' });
  }
  if (progress >= 84) {
    logs.push({
      text: '正在组织逻辑，生成检索报告初稿与格式润色...',
      active: progress < 100 && !isCompleted,
    });
  }
  if (progress === 100 || isCompleted) {
    logs.push({ text: '检索报告生成完毕', type: 'success' });
  }

  return logs;
}

export function createSearchReportJob(params: {
  turnId: string;
  userQuestion: string;
  sourceScope: ReportSourceScope;
  sourceCount: number;
}): SearchReportJob {
  const shortQ =
    params.userQuestion.length > 28
      ? `${params.userQuestion.slice(0, 28)}…`
      : params.userQuestion;

  return {
    id: `report-${params.turnId}-${Date.now()}`,
    turnId: params.turnId,
    title: `检索报告：${shortQ}`,
    progress: 0,
    status: 'generating',
    sourceScope: params.sourceScope,
    sourceCount: params.sourceCount,
  };
}

function sanitizeFileName(title: string): string {
  return `${title.replace(/[/\\?%*:|"<>]/g, '_')}.docx`;
}

export function advanceSearchReportJob(job: SearchReportJob): SearchReportJob {
  if (job.status !== 'generating') return job;

  const newProgress = Math.min(job.progress + 2, 100);
  if (newProgress < 100) {
    return { ...job, progress: newProgress };
  }

  const now = new Date();
  const pad = (n: number) => n.toString().padStart(2, '0');
  const generatedAt = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;

  return {
    ...job,
    progress: 100,
    status: 'completed',
    completedAt: generatedAt,
    generatedDocument: {
      title: job.title,
      generatedAt,
      fileName: sanitizeFileName(job.title),
    },
  };
}
