import React from 'react';
import { FileText, PenLine } from 'lucide-react';
import type { SearchReportGeneratedDocument } from './searchReportExecution';

export type SearchReportResultCardVariant = 'large' | 'compact';

type SearchReportResultCardProps = {
  document: SearchReportGeneratedDocument;
  variant: SearchReportResultCardVariant;
  onOpen?: (doc: SearchReportGeneratedDocument) => void;
};

const REPORT_PREVIEW_TITLE = '律爱多检索报告';

function displayTitle(fileName: string): string {
  return fileName.replace(/\.docx$/i, '');
}

function SearchReportA4Preview({ className = '' }: { className?: string }) {
  return (
    <div
      className={`relative aspect-[210/297] w-[84px] overflow-hidden rounded-[2px] bg-white shadow-[0_6px_18px_rgba(15,23,42,0.14)] ring-1 ring-slate-200/80 ${className}`}
      aria-hidden
    >
      <div className="h-[16%] bg-gradient-to-br from-blue-600 to-blue-500" />
      <div className="flex flex-col px-2 pb-2 pt-1.5">
        <p className="text-center text-[6px] font-extrabold leading-tight tracking-wide text-slate-800">
          {REPORT_PREVIEW_TITLE}
        </p>
        <div className="mt-1.5 space-y-1">
          <div className="h-[2px] w-full rounded-full bg-slate-100" />
          <div className="h-[2px] w-[90%] rounded-full bg-slate-100" />
          <div className="h-[2px] w-full rounded-full bg-slate-100" />
          <div className="h-[2px] w-[72%] rounded-full bg-slate-50" />
        </div>
      </div>
    </div>
  );
}

function SearchReportDocIcon({ compact }: { compact?: boolean }) {
  const boxClass = compact ? 'h-9 w-9' : 'h-10 w-10';
  const iconSize = compact ? 18 : 20;
  const badgeClass = compact ? 'h-3.5 w-3.5' : 'h-4 w-4';
  const penSize = compact ? 8 : 9;

  return (
    <div className={`relative shrink-0 ${boxClass}`}>
      <div
        className={`flex ${boxClass} items-center justify-center rounded-lg bg-blue-600 text-white shadow-sm ring-1 ring-blue-500/20`}
      >
        <FileText size={iconSize} strokeWidth={2} />
      </div>
      <div
        className={`absolute -bottom-0.5 -right-0.5 flex ${badgeClass} items-center justify-center rounded-[4px] border border-slate-100 bg-white text-blue-600 shadow-sm`}
      >
        <PenLine size={penSize} strokeWidth={2.5} />
      </div>
    </div>
  );
}

const SearchReportResultCard: React.FC<SearchReportResultCardProps> = ({
  document,
  variant,
  onOpen,
}) => {
  const title = displayTitle(document.fileName);

  if (variant === 'compact') {
    return (
      <button
        type="button"
        onClick={() => onOpen?.(document)}
        className="group flex w-full items-stretch overflow-hidden rounded-xl border border-slate-200/90 bg-white text-left shadow-sm transition-all hover:border-blue-200/80 hover:bg-blue-50/20 hover:shadow-md"
      >
        <div className="flex w-[68px] shrink-0 items-center justify-center border-r border-slate-100 bg-slate-50/80">
          <SearchReportDocIcon compact />
        </div>
        <div className="flex min-w-0 flex-1 flex-col justify-center px-3.5 py-2.5">
          <div className="truncate text-[13px] font-bold text-slate-900">{title}</div>
          <div className="mt-0.5 text-[11px] font-medium tabular-nums text-slate-500">
            {document.generatedAt}
          </div>
        </div>
      </button>
    );
  }

  return (
    <button
      type="button"
      onClick={() => onOpen?.(document)}
      className="group relative w-full max-w-[400px] overflow-hidden rounded-xl border border-slate-200/90 bg-[#f4f6f8] p-3.5 text-left shadow-sm transition-all hover:border-blue-200/80 hover:bg-blue-50/30 hover:shadow-md"
    >
      <div className="pointer-events-none absolute right-0 top-[42%] z-0 translate-x-1.5">
        <SearchReportA4Preview />
      </div>

      <div className="relative z-10 min-w-0 pr-[72px]">
        <SearchReportDocIcon compact />
        <h4 className="mt-2 line-clamp-2 text-[14px] font-extrabold leading-snug text-slate-900">
          {title}
        </h4>
        <p className="mt-1 text-[11px] font-medium tabular-nums text-slate-500">
          {document.generatedAt}
        </p>
      </div>
    </button>
  );
};

export default SearchReportResultCard;
