export type ActionHoverItem = {
  id: string;
  label: string;
  icon?: React.ReactNode;
};

const ActionFlyoutPanel: React.FC<{
  items: ActionHoverItem[];
  onSelect: (id: string) => void;
  itemClassName?: string;
}> = ({ items, onSelect, itemClassName = MORE_MENU_ITEM_CLASS }) => (
  <div className={MORE_MENU_PANEL_CLASS} role="menu">
    {items.map((item) => (
      <button
        key={item.id}
        type="button"
        role="menuitem"
        onClick={() => onSelect(item.id)}
        onMouseDown={(e) => e.stopPropagation()}
        className={itemClassName}
      >
        {item.icon}
        {item.label}
      </button>
    ))}
  </div>
);

