export type SaveTargetClickMenuProps = {
  label: string;
  items: SaveTargetOption[];
  onConfirm: (selectedIds: string[]) => void;
  buttonClassName?: string;
  disabled?: boolean;
  disabledReason?: string;
  confirmLabel?: string;
  /** 单选时一次只能选一个目标；默认多选 */
  selectionMode?: 'single' | 'multiple';
};

const SaveTargetClickMenu: React.FC<SaveTargetClickMenuProps> = ({
  label,
  items,
  onConfirm,
  buttonClassName = 'shrink-0 rounded-lg px-2.5 py-1 text-[11px] font-extrabold transition ring-1',
  disabled = false,
  disabledReason,
  confirmLabel = '确认',
  selectionMode = 'multiple',
}) => {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const menu = useClickMenu({
    onClose: () => setSelectedIds([]),
  });

  const toggleItem = (id: string) => {
    if (selectionMode === 'single') {
      setSelectedIds([id]);
      return;
    }
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const handleConfirm = () => {
    if (selectedIds.length === 0) return;
    onConfirm(selectedIds);
    menu.close();
  };

  const handleToggle = () => {
    if (disabled) return;
    menu.toggle();
  };

  return (
    <div ref={menu.rootRef} className={`relative ${disabled ? 'group' : ''}`}>
      {disabled && disabledReason ? (
        <div
          role="tooltip"
          className="pointer-events-none absolute bottom-[calc(100%+6px)] right-0 z-[60] hidden w-max max-w-[240px] rounded-lg bg-slate-800 px-2.5 py-1.5 text-left text-[11px] font-bold leading-snug text-white shadow-lg group-hover:block"
        >
          {disabledReason}
        </div>
      ) : null}
      <button
        type="button"
        onClick={handleToggle}
        disabled={disabled}
        aria-expanded={disabled ? undefined : menu.open}
        aria-haspopup="menu"
        aria-disabled={disabled}
        className={`${buttonClassName} ${
          disabled
            ? 'cursor-not-allowed bg-slate-100 text-slate-400 ring-slate-200/80'
            : menu.open
              ? 'bg-blue-100 text-blue-800 ring-blue-200/90'
              : 'bg-blue-50 text-blue-700 ring-blue-100/90 hover:bg-blue-100 hover:text-blue-800'
        }`}
      >
        {label}
      </button>

      {!disabled && menu.open ? (
        <div className={DROPDOWN_ANCHOR_CLASS}>
          <div className="relative">
            <span
              className="absolute -top-1.5 right-6 h-3 w-3 rotate-45 border-l border-t border-slate-200/90 bg-white"
              aria-hidden
            />
            <SaveTargetSelectionPanel
              items={items}
              selectedIds={selectedIds}
              onToggle={toggleItem}
              onConfirm={handleConfirm}
              confirmLabel={confirmLabel}
              selectionMode={selectionMode}
            />
          </div>
        </div>
      ) : null}
    </div>
  );
};

export default SaveTargetClickMenu;
