import { useCallback, useState } from 'react';
import { formatModelDisplay, isV4Model } from './modelConfig';

export type SearchMode = 'normal' | 'deep' | 'research';

export type SearchSourceKey = 'web' | 'fabao' | 'knowledge';

export type SearchSources = Record<SearchSourceKey, boolean>;

export type SearchPhase = 'compose' | 'results';

const defaultSources: SearchSources = {
  web: true,
  fabao: true,
  knowledge: true,
};

export function useSearchLogic() {
  const [query, setQuery] = useState('');
  const [phase, setPhase] = useState<SearchPhase>('compose');
  const [submittedQuery, setSubmittedQuery] = useState('');
  const [followUp, setFollowUp] = useState('');
  const [searchMode, setSearchMode] = useState<SearchMode>('normal');
  const [sources, setSources] = useState<SearchSources>({ ...defaultSources });
  const [modelId, setModelIdState] = useState('DeepSeek-V4-Flash');
  const [thinkingEnabled, setThinkingEnabledState] = useState(false);

  const setModelId = useCallback((id: string) => {
    setModelIdState(id);
    if (!isV4Model(id)) {
      setThinkingEnabledState(false);
    }
  }, []);

  const setThinkingEnabled = useCallback((enabled: boolean) => {
    setThinkingEnabledState(enabled);
  }, []);

  const reset = useCallback(() => {
    setQuery('');
    setFollowUp('');
    setPhase('compose');
    setSubmittedQuery('');
    setSearchMode('normal');
    setSources({ ...defaultSources });
  }, []);

  const toggleSource = useCallback((key: SearchSourceKey) => {
    setSources((prev) => {
      const next = { ...prev, [key]: !prev[key] };
      const anyOn = next.web || next.fabao || next.knowledge;
      if (!anyOn) return prev;
      return next;
    });
  }, []);

  const applySuggestion = useCallback((text: string) => {
    setQuery(text);
  }, []);

  const submit = useCallback(() => {
    const q = query.trim();
    if (!q) return;
    setSubmittedQuery(q);
    setPhase('results');
    setFollowUp('');
  }, [query]);

  const newSearch = useCallback(() => {
    setPhase('compose');
    setFollowUp('');
  }, []);

  const submitFollowUp = useCallback(() => {
    if (!followUp.trim()) return;
    // 演示：后续可在此发起追问请求并更新结果区
    setFollowUp('');
  }, [followUp]);

  return {
    query,
    setQuery,
    phase,
    submittedQuery,
    followUp,
    setFollowUp,
    searchMode,
    setSearchMode,
    sources,
    toggleSource,
    modelId,
    setModelId,
    thinkingEnabled,
    setThinkingEnabled,
    modelDisplayLabel: formatModelDisplay(modelId, thinkingEnabled),
    reset,
    submit,
    newSearch,
    submitFollowUp,
    applySuggestion,
  };
}
