import React from 'react';
import { X } from 'lucide-react';

export type FeedbackReasonOption = {
  id: string;
  label: string;
};

export const DISLIKE_FEEDBACK_REASONS: FeedbackReasonOption[] = [
  { id: 'inaccurate', label: '内容不准确' },
  { id: 'wrong_source', label: '引用来源有误' },
  { id: 'not_answered', label: '没有回答问题' },
  { id: 'missing_info', label: '遗漏重要信息' },
  { id: 'unclear_logic', label: '逻辑不清晰' },
  { id: 'irrelevant', label: '结果不相关' },
  { id: 'format_issue', label: '格式问题' },
  { id: 'other', label: '其他' },
];

export type AnswerFeedbackDraft = {
  selectedReasonIds: string[];
  otherText: string;
};

type AnswerFeedbackPanelProps = {
  title: string;
  reasons: FeedbackReasonOption[];
  draft: AnswerFeedbackDraft;
  onToggleReason: (id: string) => void;
  onOtherTextChange: (text: string) => void;
  onClose: () => void;
  onSubmit: () => void;
};

const AnswerFeedbackPanel: React.FC<AnswerFeedbackPanelProps> = ({
  title,
  reasons,
  draft,
  onToggleReason,
  onOtherTextChange,
  onClose,
  onSubmit,
}) => {
  const showOtherInput = draft.selectedReasonIds.includes('other');
  const canSubmit =
    draft.selectedReasonIds.length > 0 || draft.otherText.trim().length > 0;

  return (
    <div className="mt-3 rounded-2xl border border-slate-200/90 bg-white p-4 shadow-sm shadow-slate-100/80">
      <div className="flex items-start justify-between gap-3">
        <p className="text-[14px] font-extrabold text-slate-800">{title}</p>
        <button
          type="button"
          onClick={onClose}
          className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-400 transition hover:bg-slate-100 hover:text-slate-600"
          aria-label="关闭反馈"
        >
          <X size={16} strokeWidth={2} />
        </button>
      </div>

      <div className="mt-3 flex flex-wrap gap-2">
        {reasons.map((reason) => {
          const selected = draft.selectedReasonIds.includes(reason.id);
          return (
            <button
              key={reason.id}
              type="button"
              onClick={() => onToggleReason(reason.id)}
              className={`rounded-full px-3.5 py-1.5 text-[12px] font-bold transition ${
                selected
                  ? 'bg-slate-200/90 text-slate-800'
                  : 'border border-slate-200 bg-white text-slate-600 hover:border-slate-300 hover:bg-slate-50'
              }`}
            >
              {reason.label}
            </button>
          );
        })}
      </div>

      {showOtherInput ? (
        <div className="mt-3 flex items-center gap-2 rounded-xl bg-slate-100/90 px-3 py-2">
          <input
            type="text"
            value={draft.otherText}
            onChange={(e) => onOtherTextChange(e.target.value)}
            placeholder="(可选) 告诉我们更多关于你的使用体验"
            className="min-w-0 flex-1 bg-transparent text-[12px] font-medium text-slate-700 placeholder:text-slate-400 focus:outline-none"
          />
          <button
            type="button"
            disabled={!canSubmit}
            onClick={onSubmit}
            className={`shrink-0 rounded-full px-4 py-1.5 text-[12px] font-extrabold transition ${
              canSubmit
                ? 'bg-blue-600 text-white shadow-sm hover:bg-blue-700 active:scale-[0.98]'
                : 'cursor-not-allowed bg-blue-200/80 text-white/90'
            }`}
          >
            提交
          </button>
        </div>
      ) : (
        <div className="mt-3 flex justify-end">
          <button
            type="button"
            disabled={!canSubmit}
            onClick={onSubmit}
            className={`rounded-full px-5 py-1.5 text-[12px] font-extrabold transition ${
              canSubmit
                ? 'bg-blue-600 text-white shadow-sm hover:bg-blue-700 active:scale-[0.98]'
                : 'cursor-not-allowed bg-blue-200/80 text-white/90'
            }`}
          >
            提交
          </button>
        </div>
      )}
    </div>
  );
};

export default AnswerFeedbackPanel;
